-- ------------------------------------------------------------
-- 10. TOP REVENUE MONTHS
-- Purpose:
-- Identify the strongest months by delivered product revenue.
-- ------------------------------------------------------------

SELECT
    DATE_TRUNC(
        'month',
        o.order_purchase_timestamp::timestamp
    ) AS month,

    COUNT(DISTINCT o.order_id)
        AS delivered_orders,

    ROUND(
        SUM(oi.price)::numeric,
        2
    ) AS product_revenue

FROM orders AS o

INNER JOIN order_items AS oi
    ON o.order_id = oi.order_id

WHERE o.order_status = 'delivered'

GROUP BY
    DATE_TRUNC(
        'month',
        o.order_purchase_timestamp::timestamp
    )

ORDER BY product_revenue DESC

LIMIT 10;

